later.src/store/cart.ts:
import { track } from "../analytics/track";

export interface CartItem {
  id: string;
  priceCents: number;
}

const items: CartItem[] = [];

export function add(item: CartItem): void {
  items.push(item);
  track("add_to_cart", { id: item.id, priceCents: item.priceCents });
}
